package merge

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// REPAIR runs [hooks].repair too, so the repairguard that keeps the
// regenerate phase's generated files also guards it: otherwise REPAIR would
// reformat what the regenerate phase kept, a moment later.

const (
	generatorFacade = "// Code generated by stub. DO NOT EDIT.\n\npackage facade\n\nconst a = 1\nconst b = 2"
	formattedFacade = "// Code generated by stub. DO NOT EDIT.\n\npackage facade\n\nconst (\n\ta = 1\n\tb = 2\n)"
)

// repairGeneratedRepo: main holds the generator's facade.go and a sweatfile
// whose repair rewrites facade.go (and, with touchA, a.txt) and amends; the
// feature branch adds a.txt. extra is appended to the [hooks] table.
func repairGeneratedRepo(t *testing.T, touchA bool, extra string) (repoDir, wtPath, head string) {
	t.Helper()
	repoDir = setupRepo(t)
	formatted := filepath.Join(t.TempDir(), "formatted.go")
	if err := os.WriteFile(formatted, []byte(formattedFacade+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	writeFile(t, repoDir, "facade.go", generatorFacade+"\n")
	runGit(t, repoDir, "add", "facade.go")
	runGit(t, repoDir, "commit", "-m", "generated facade")
	repair := "cp " + formatted + " facade.go"
	if touchA {
		repair += " && printf formatted > a.txt"
	}
	repair += " && git commit -q -a --amend --no-edit"
	writeRepoSweatfile(t, repoDir, fmt.Sprintf("[hooks]\npre-commit = \"true\"\nrepair = %q\n%s", repair, extra))
	wtPath = setupWorktree(t, repoDir, "feature")
	writeFile(t, wtPath, "a.txt", "a")
	runGit(t, wtPath, "add", "a.txt")
	runGit(t, wtPath, "commit", "-m", "feature commit")
	return repoDir, wtPath, runGit(t, wtPath, "rev-parse", "HEAD")
}

func TestPrepareMergeRepairKeepsTheGeneratorsBytes(t *testing.T) {
	repoDir, wtPath, head := repairGeneratedRepo(t, true, "")

	pinned, tests, err := runPrepare(t, repoDir, wtPath, "feature")
	if err != nil {
		t.Fatalf("PrepareMerge: %v (points: %v)", err, testDescs(tests))
	}
	if pinned == head {
		t.Fatalf("pinned = %s, want repair's amend of a.txt kept", pinned)
	}
	if got := runGit(t, wtPath, "show", pinned+":facade.go"); got != generatorFacade {
		t.Errorf("pinned facade.go = %q, want the generator's bytes", got)
	}
	if got := runGit(t, wtPath, "show", pinned+":a.txt"); got != "formatted" {
		t.Errorf("pinned a.txt = %q, want repair's edit kept", got)
	}
	tr, ok := findTest(tests, "repair kept generated files")
	if !ok || !tr.OK || !strings.Contains(tr.Description, "facade.go") || !strings.Contains(tr.Description, "skip-generated") {
		t.Errorf("want an ok point naming facade.go and skip-generated, got %+v (all: %v)", tr, testDescs(tests))
	}
	if tr, ok := findTest(tests, "repair feature"); !ok || !tr.OK || !strings.Contains(tr.Description, "amended") {
		t.Errorf("want an ok amended repair point, got %+v", tr)
	}
	if st := runGit(t, wtPath, "status", "--porcelain", "--untracked-files=no"); st != "" {
		t.Errorf("worktree not clean: %q", st)
	}
}

func TestPrepareMergeRepairThatOnlyReformatsGeneratedFilesIsAlreadyConformant(t *testing.T) {
	repoDir, wtPath, head := repairGeneratedRepo(t, false, "")

	pinned, tests, err := runPrepare(t, repoDir, wtPath, "feature")
	if err != nil {
		t.Fatalf("PrepareMerge: %v (points: %v)", err, testDescs(tests))
	}
	if pinned != head {
		t.Errorf("pinned = %s, want the pre-repair %s", pinned, head)
	}
	if tr, ok := findTest(tests, "repair feature"); !ok || !strings.Contains(tr.Description, "already conformant") {
		t.Errorf("want an already-conformant repair point, got %+v (all: %v)", tr, testDescs(tests))
	}
}

func TestPrepareMergeRepairRefusesUnderFail(t *testing.T) {
	repoDir, wtPath, head := repairGeneratedRepo(t, true, "repair-generated = \"fail\"\n")

	_, tests, err := runPrepare(t, repoDir, wtPath, "feature")
	if err == nil || !strings.Contains(err.Error(), "facade.go") {
		t.Fatalf("err = %v, want a refusal naming facade.go (points: %v)", err, testDescs(tests))
	}
	if tr, ok := findTest(tests, "repair feature"); !ok || tr.OK {
		t.Errorf("want a failing repair point, got %+v", tr)
	}
	if got := runGit(t, wtPath, "rev-parse", "HEAD"); got != head {
		t.Errorf("HEAD = %s, want the pre-repair %s", got, head)
	}
}

func TestPrepareMergeRepairIgnoresARepoLayerAllow(t *testing.T) {
	repoDir, wtPath, _ := repairGeneratedRepo(t, true, "repair-generated = \"allow\"\n")

	pinned, tests, err := runPrepare(t, repoDir, wtPath, "feature")
	if err != nil {
		t.Fatalf("PrepareMerge: %v (points: %v)", err, testDescs(tests))
	}
	if got := runGit(t, wtPath, "show", pinned+":facade.go"); got != generatorFacade {
		t.Errorf("pinned facade.go = %q, want the generator's bytes (a repo-layer allow is not honoured)", got)
	}
}

func TestPrepareMergeRepairHonoursAGlobalAllow(t *testing.T) {
	repoDir, wtPath, _ := repairGeneratedRepo(t, true, "")
	writeGlobalSweatfile(t, "[hooks]\nrepair-generated = \"allow\"\n")

	pinned, tests, err := runPrepare(t, repoDir, wtPath, "feature")
	if err != nil {
		t.Fatalf("PrepareMerge: %v (points: %v)", err, testDescs(tests))
	}
	if got := runGit(t, wtPath, "show", pinned+":facade.go"); got != formattedFacade {
		t.Errorf("pinned facade.go = %q, want repair's bytes under a global allow", got)
	}
	if _, ok := findTest(tests, "repair kept generated files"); ok {
		t.Errorf("allow must not report kept files: %v", testDescs(tests))
	}
}

// Without [hooks].pre-commit, repair may be the generator: its edit is kept.
func TestPrepareMergeRepairStandsAsideWithoutAPreCommitHook(t *testing.T) {
	repoDir, wtPath, _ := repairGeneratedRepo(t, true, "disable-pre-commit = true\n")

	pinned, tests, err := runPrepare(t, repoDir, wtPath, "feature")
	if err != nil {
		t.Fatalf("PrepareMerge: %v (points: %v)", err, testDescs(tests))
	}
	if got := runGit(t, wtPath, "show", pinned+":facade.go"); got != formattedFacade {
		t.Errorf("pinned facade.go = %q, want repair's bytes (repair is the only hook)", got)
	}
}
